import type { FastifyInstance, FastifyRequest } from 'fastify';
import swagger from '@fastify/swagger';
import swaggerUi from '@fastify/swagger-ui';
import { Ajv, type ErrorObject, type ValidateFunction } from 'ajv';
import { SHARED_SCHEMAS } from './schemas.js';

/**
 * The OpenAPI spec and docs page (docs/api_roadmap.md step 3).
 *
 * - The spec is generated by @fastify/swagger from each route's `schema` and served at
 *   `/docs/json` (and `/docs/yaml`); Swagger UI at `/docs`, both without sign-in. "Try it
 *   out" sends real requests with the browser's session cookie, or with a token entered
 *   under "Authorize".
 * - Request schemas are enforced: bodies exactly as sent (no type coercion), query strings
 *   and path parameters with coercion (they're always text). Failures become
 *   `400 INVALID_REQUEST` problem details naming each field (`validationProblem`). A body
 *   schema marked with `handlerValidated()` is documentation only: the route checks it itself.
 * - Response schemas only document: responses are serialized with plain JSON.stringify,
 *   so a schema can never drop or change a field. With `checkResponses` (on in tests),
 *   every JSON response is checked against its schema, undocumented fields included, and a
 *   mismatch fails the request loudly -- so the test suite keeps the spec honest.
 */

export const OPENAPI_TAGS = [
  { name: 'Sign-in', description: 'Signing in and out, and your own account. Scripts use the `token` from a plain login as `Authorization: Bearer <token>`.' },
  { name: 'Projects', description: 'Projects; each one holds suites, cases, plans and runs. Its prefix starts every case id (SHOP-101).' },
  { name: 'Specification', description: 'Suites (a tree) and test cases. A case has a readable id (SHOP-101), unversioned fields (title, priority, execution type) and versioned content.' },
  { name: 'Versions', description: "A case's content: summary, preconditions and steps. Edited on a DRAFT, then approved; DRAFT → APPROVED → DEPRECATED, and Restore back to APPROVED." },
  { name: 'Custom field values', description: 'Values of admin-defined custom fields on cases and suites. Not versioned.' },
  { name: 'Search', description: 'Finding cases by text and by property; the same filters work in reports.' },
  { name: 'Plans', description: 'Test plans: a set of cases, each pinned at a version.' },
  { name: 'Runs and results', description: 'Test runs of a plan, and the results recorded in them (one at a time, or in CI batches).' },
  { name: 'Reports', description: 'Run summaries, trends, test health, case history, breakdowns. The catalog says what each report answers and takes.' },
  { name: 'Report email', description: 'Emailing reports to anyone, now or on a schedule.' },
  { name: 'Import', description: 'Importing suites and cases: TestLink XML, JUnit XML, Testify JSON, CSV, TestRail CSV. Preview first, then import.' },
  { name: 'Export', description: 'Exporting suites and cases, or a run\'s results, as JSON or CSV.' },
  { name: 'API tokens', description: 'Tokens for CI and scripts. Each works only in its own project.' },
  { name: 'Admin: users and roles', description: 'Users, roles, project roles and permission overrides. Not available to API tokens.' },
  { name: 'Admin: custom fields', description: 'Defining custom fields for cases and suites. Not available to API tokens.' },
  { name: 'Admin: email', description: 'The mail server for report emails. Not available to API tokens.' },
  { name: 'Admin: audit log', description: 'The security audit log. Not available to API tokens.' },
  { name: 'Operations', description: 'Health check and the MCP endpoint for AI agents.' },
];

const SPEC_DESCRIPTION = `The Testify REST API. Everything the web app does goes through it.

**Authentication** — send one of:
- \`Authorization: Bearer tf_ci_…\`: an API token from Admin Panel → API Tokens, bound to one project. The right choice for CI and scripts.
- \`Authorization: Bearer <jwt>\`: the \`token\` from \`POST /api/v1/auth/login\`.
- The web app's session cookie: if you're signed in to Testify in this browser, "Try it out" just works.

**Conventions** (RFC 03 §1): lists and creation sit under the parent, each item has its own address; \`PATCH\` changes only the fields sent; creating answers 201 with the item wrapped in its name, deleting answers 204; \`?force=true\` deletes something that still contains things. Ids are named after their database columns (\`test_plan_id\`, \`test_run_id\`, …). Every error is problem details (\`application/problem+json\`) with a \`code\` and a \`detail\`.`;

function ajvFor(coerce: boolean) {
  const ajv = new Ajv({
    allErrors: true,
    coerceTypes: coerce,
    useDefaults: false,
    removeAdditional: false,
    // Spec-only keywords (description, example, x-...) are allowed.
    strict: false,
  });
  for (const s of SHARED_SCHEMAS) ajv.addSchema(s);
  return ajv;
}

/** `/steps/0/action` → `steps[0].action`. */
function fieldName(instancePath: string, extra?: string): string {
  const parts = instancePath.split('/').filter(Boolean);
  if (extra) parts.push(extra);
  return parts.map((p, i) => (/^\d+$/.test(p) ? `[${p}]` : i === 0 ? p : `.${p}`)).join('');
}

function reasonFor(e: ErrorObject): string {
  const p = e.params as Record<string, any>;
  switch (e.keyword) {
    case 'required':
      return 'is required';
    case 'type': {
      const types = (Array.isArray(p.type) ? p.type : String(p.type).split(',')).map((t: string) => (t === 'null' ? 'null' : t === 'integer' ? 'a whole number' : /^[aeiou]/.test(t) ? `an ${t}` : `a ${t}`));
      return `must be ${types.join(' or ')}`;
    }
    case 'enum':
      return `must be one of: ${(p.allowedValues as unknown[]).join(', ')}`;
    case 'const':
      return `must be ${JSON.stringify(p.allowedValue)}`;
    case 'minLength':
      return p.limit === 1 ? "can't be empty" : `must be at least ${p.limit} characters`;
    case 'maxLength':
      return `can be at most ${p.limit} characters`;
    case 'minimum':
      return `must be at least ${p.limit}`;
    case 'maximum':
      return `can be at most ${p.limit}`;
    case 'minItems':
      return `needs at least ${p.limit} item${p.limit === 1 ? '' : 's'}`;
    case 'maxItems':
      return `can have at most ${p.limit} items`;
    case 'additionalProperties':
      return "isn't a known field";
    case 'pattern':
      return 'has the wrong format';
    default:
      return e.message ?? 'is invalid';
  }
}

/** Ajv errors as `invalid_params` ({ name, reason }), one per field and reason. */
export function validationProblem(errors: ErrorObject[], context?: string): Array<{ name: string; reason: string }> {
  const seen = new Set<string>();
  const out: Array<{ name: string; reason: string }> = [];
  for (const e of errors) {
    // An `anyOf`/`oneOf` failure repeats what its branches already said.
    if (e.keyword === 'anyOf' || e.keyword === 'oneOf' || e.keyword === 'if') continue;
    const p = e.params as Record<string, any>;
    const extra = e.keyword === 'required' ? p.missingProperty : e.keyword === 'additionalProperties' ? p.additionalProperty : undefined;
    let name = fieldName(e.instancePath, extra);
    if (!name) name = context === 'body' ? 'body' : context ?? 'request';
    const reason = reasonFor(e);
    const key = `${name}|${reason}`;
    if (!seen.has(key)) {
      seen.add(key);
      out.push({ name, reason });
    }
  }
  return out;
}

// ---- Response checking (tests) ----

/** Deep copy where every object that lists `properties` rejects unlisted ones, unless it says otherwise. */
function closeObjects(schema: unknown): unknown {
  if (Array.isArray(schema)) return schema.map(closeObjects);
  if (!schema || typeof schema !== 'object') return schema;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(schema)) out[k] = closeObjects(v);
  if (out.properties && out.additionalProperties === undefined) out.additionalProperties = false;
  return out;
}

function pickResponseSchema(responses: Record<string, any>, status: number, contentType: string): any | undefined {
  const entry = responses[String(status)] ?? responses[`${String(status)[0]}xx`] ?? responses.default;
  if (!entry) return undefined;
  if (entry.content) {
    const base = contentType.split(';')[0].trim();
    return entry.content[base]?.schema ?? Object.values<any>(entry.content)[0]?.schema;
  }
  return entry;
}

export interface OpenApiOptions {
  /** Check every JSON response against its route's schema (tests). */
  checkResponses?: boolean;
}

/** A registered route and whether the spec describes it (see `app.openApiRoutes`). */
export interface RegisteredRoute {
  method: string;
  url: string;
  /** Has a tag, so it's in the spec. */
  documented: boolean;
  /** Deliberately left out (`schema.hide`). */
  hidden: boolean;
}

declare module 'fastify' {
  interface FastifyInstance {
    /** Every route registered after the OpenAPI setup, for the test that none is undocumented. */
    openApiRoutes: RegisteredRoute[];
  }
}

/** Registers the spec, the docs page, the validator and (optionally) the response check. Call before any route. */
export async function registerOpenApi(app: FastifyInstance, options: OpenApiOptions = {}) {
  for (const s of SHARED_SCHEMAS) app.addSchema(s);

  const routes: RegisteredRoute[] = [];
  app.decorate('openApiRoutes', routes);
  app.addHook('onRoute', (route) => {
    const schema = route.schema as { tags?: string[]; hide?: boolean } | undefined;
    for (const method of [route.method].flat()) {
      if (method === 'HEAD') continue;
      routes.push({ method, url: route.url, documented: Boolean(schema?.tags?.length) && !schema?.hide, hidden: Boolean(schema?.hide) });
    }
  });

  await app.register(swagger, {
    openapi: {
      openapi: '3.1.0',
      info: { title: 'Testify API', version: '1.0.0', description: SPEC_DESCRIPTION },
      tags: OPENAPI_TAGS,
      components: {
        securitySchemes: {
          bearerAuth: {
            type: 'http',
            scheme: 'bearer',
            description: 'An API token (`tf_ci_…`, from Admin Panel → API Tokens) or the `token` from `POST /api/v1/auth/login`.',
          },
          sessionCookie: {
            type: 'apiKey',
            in: 'cookie',
            name: 'testify_session',
            description: "The web app's sign-in. Set by `POST /api/v1/auth/login` with `session: \"cookie\"`; changes also need the `X-Testify-Client: web` header (this page adds it).",
          },
        },
      },
      security: [{ bearerAuth: [] }, { sessionCookie: [] }],
    },
    // Shared schemas become #/components/schemas/<$id>.
    refResolver: { buildLocalReference: (json: any, _baseUri: any, _fragment: any, i: number) => json.$id || `def-${i}` },
    // Routes without a tag aren't documented yet; leave them out rather than show them bare.
    hideUntagged: true,
  });

  await app.register(swaggerUi, {
    routePrefix: '/docs',
    staticCSP: true,
    // No top bar: its "Explore" box and Fastify logo mean nothing here.
    theme: {
      title: 'Testify API',
      css: [{ filename: 'testify.css', content: '.swagger-ui .topbar { display: none; }' }],
    },
    uiConfig: {
      docExpansion: 'list',
      deepLinking: true,
      defaultModelsExpandDepth: 0,
      displayRequestDuration: true,
      // Cookie sign-ins must send this header on changes (the CSRF guard in middleware/auth.ts).
      // This page is served by Testify itself, so it may.
      requestInterceptor: (req: any) => {
        req.headers['X-Testify-Client'] = 'web';
        return req;
      },
    } as any,
  });

  // Validation (see the comment at the top).
  const strictAjv = ajvFor(false);
  const coercingAjv = ajvFor(true);
  app.setValidatorCompiler(({ schema, httpPart }) => {
    if ((schema as any)['x-validated-by-handler']) return () => true;
    return (httpPart === 'body' ? strictAjv : coercingAjv).compile(schema as object);
  });
  // Responses are never reshaped by their schemas.
  app.setSerializerCompiler(() => (data: unknown) => JSON.stringify(data));

  if (options.checkResponses) {
    const checkAjv = new Ajv({ allErrors: true, strict: false });
    for (const s of SHARED_SCHEMAS) checkAjv.addSchema(closeObjects(s) as object);
    const compiled = new WeakMap<object, ValidateFunction>();

    app.addHook('onSend', async (request: FastifyRequest, reply, payload) => {
      const responses = (request.routeOptions.schema as any)?.response;
      if (!responses) return payload;
      // 5xx is the generic internal error (and what a mismatch below turns into).
      if (reply.statusCode >= 500) return payload;
      const contentType = String(reply.getHeader('content-type') ?? '');
      const where = `${request.method} ${request.routeOptions.url} ${reply.statusCode}`;
      // An error status the route doesn't list is still checked against the general error shape.
      const schema = pickResponseSchema(responses, reply.statusCode, contentType) ?? (reply.statusCode >= 400 ? { $ref: 'Problem#' } : undefined);
      if (!schema) {
        throw new SpecMismatch(`${where}: the spec documents no response for this status`);
      }
      if (schema.type === 'null') {
        if (payload !== undefined && payload !== null && payload !== '') throw new SpecMismatch(`${where}: documented as no body, but sent one`);
        return payload;
      }
      if (!/json/.test(contentType) || typeof payload !== 'string') return payload;
      let validate = compiled.get(schema);
      if (!validate) {
        validate = checkAjv.compile(closeObjects(schema) as object);
        compiled.set(schema, validate);
      }
      if (!validate(JSON.parse(payload))) {
        const problems = validationProblem(validate.errors ?? []).map((p) => `${p.name || '(body)'} ${p.reason}`);
        throw new SpecMismatch(`${where}: response doesn't match the spec: ${problems.join('; ')}`);
      }
      return payload;
    });
  }
}

/** A response that doesn't match its documented schema (only raised with `checkResponses`). */
export class SpecMismatch extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SpecMismatch';
    // Printed straight away: the error handler hides 500s from clients and doesn't log in tests.
    console.error(`[openapi] ${message}`);
  }
}
